package net.civeira.phylax.feature.observe.observedalertrule.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject.ThresholdVO;

@RequiredArgsConstructor
public class ThresholdValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ThresholdVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getThreshold() {
    return value.map(ThresholdVO::getThreshold);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ThresholdVO> getThresholdValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ThresholdVO readThreshold(final Optional<ObservedAlertRule> original,
      final ConstraintFailList fails) {
    ThresholdVO result =
        value.orElse(original.map(ObservedAlertRule::getThresholdValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "threshold", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param threshold
   * @return
   */
  public T threshold(ThresholdVO threshold) {
    this.value = Optional.of(threshold);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param threshold
   * @return
   */
  public T threshold(Optional<ThresholdVO> threshold) {
    this.value = threshold;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param threshold
   * @return
   */
  public T threshold(Integer threshold) {
    this.value = Optional.of(ThresholdVO.from(threshold));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetThreshold() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetThresholdIfMatches(final String field) {
    if ("threshold".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
